contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(other != address(this), "other must not be the test contract");
        require(other != address(c), "other must not be the contract itself");
        require(amount <= address(this).balance, "insufficient balance");

        uint256 beforeOther = c.balances(other); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 afterOther = c.balances(other); if (__ESBMC_reverted()) return;

        assert(afterOther == beforeOther);
    }

    receive() external payable {}
}

